  ('41972ed6-f468-5f4b-b6fe-b15bb333d2c8', '22222222-2222-2222-2222-222222222219', 'short', '球的截面：一个平面截球，平面与球面的交线是一个圆，当平面经过球 心时，这个圆叫做球的大圆，当平面不过球心时，这个圆叫做球的小圆.', null, '', '', '数学/第9章 立体几何  含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 38, null),
  ('fc94d34a-2d62-56f7-bf6c-a99341ce4e50', '22222222-2222-2222-2222-222222222219', 'short', '球心和截面圆心的连线垂直于截面.', null, '', '', '数学/第9章 立体几何  含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 39, null),
  ('e44e9c05-1aca-51e0-9888-2875c60ba098', '22222222-2222-2222-2222-222222222219', 'short', '球心到截面的距离𝑑与球半径𝑅及截面圆半径𝑟的关系：𝑅2 = 𝑑2 + 𝑟2.', null, '', '', '数学/第9章 立体几何  含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 40, null),
